def pol(x, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(x[:, j], axis=1) for k in range(d + 1) for j in combinations_with_replacement(range(x.shape[1]), k)])

def fit_vp(u, v, base, extra, starts):
    from scipy.optimize import least_squares

    def err(h):
        a = np.c_[base, extra(u, h)]
        return a @ fit(a, v) - v
    sol = min((least_squares(lambda h: err(h).ravel(), h, bounds=(0.12, 12.0), max_nfev=180) for h in starts), key=lambda z: z.cost)
    a = np.c_[base, extra(u, sol.x)]
    return (np.std(err(sol.x), axis=0), sol.x, fit(a, v))

def calibration(s):
    from scipy.optimize import least_squares
    p = s['panel_a']
    (u, v) = (p['u'], p['v'])
    keep = np.linalg.norm(v, axis=1) < 5

    def features(u, j):
        a = u[:, j]
        b = u[:, (j + 1) % 4]
        return np.c_[pol(u, 1), a * b, a ** 3]
    cc = np.column_stack([fit(features(u[keep], j), v[keep, j]) for j in range(4)])

    def f(u):
        return np.column_stack([features(u, j) @ cc[:, j] for j in range(4)])

    def inv(x):
        guess = np.linalg.solve(cc[1:5].T, (x - cc[0]).T).T
        ret = []
        for (a, b) in zip(guess, x):
            if np.linalg.norm(f(a[None])[0] - b) < 1e-12:
                ret.append(a)
                continue
            fn = lambda z: f(z[None])[0] - b
            r = least_squares(fn, a, max_nfev=80, gtol=1e-12)
            pool = [r.x]
            if np.linalg.norm(r.fun) > 1e-07 or np.max(abs(r.x)) > 1.35:
                for ini in [np.clip(a, -1.2, 1.2), np.zeros(4), *[a + k for k in [np.eye(4)[i] * v for i in range(4) for v in [-1, 1]]]]:
                    pool.append(least_squares(fn, ini, max_nfev=80, gtol=1e-12).x)
            ret.append(min(pool, key=lambda z: 10000.0 * np.linalg.norm(fn(z)) + np.sum(abs(z) ** 4)))
        return np.array(ret)
    return (inv, f, cc, np.std(f(u[keep]) - v[keep], axis=0))
